"""Document Layout Analyzer for DocMind."""
import re
from typing import Dict, Any, List


class DocumentLayoutAnalyzer:
    """Analyzes document structure to detect zones and reading order."""

    def _detect_headers(self, lines: List[str]) -> List[Dict[str, Any]]:
        """Detect header lines based on formatting heuristics."""
        headers = []
        for i, line in enumerate(lines):
            stripped = line.strip()
            if not stripped:
                continue
            is_header = False
            level = 3

            # ALL CAPS lines are likely headers
            if stripped.isupper() and len(stripped.split()) <= 10:
                is_header = True
                level = 1
            # Lines ending with colon are often section headers
            elif stripped.endswith(":") and len(stripped.split()) <= 8:
                is_header = True
                level = 2
            # Short bold-like lines (all words capitalized, no period)
            elif (
                stripped.istitle()
                and len(stripped.split()) <= 8
                and not stripped.endswith(".")
            ):
                is_header = True
                level = 2
            # Lines with leading # markdown headers
            elif stripped.startswith("#"):
                is_header = True
                level = min(3, stripped.count("#"))

            if is_header:
                headers.append({
                    "type": "header",
                    "level": level,
                    "text": stripped,
                    "line_number": i,
                })
        return headers

    def _detect_tables(self, lines: List[str]) -> List[Dict[str, Any]]:
        """Detect table regions based on delimiter patterns."""
        tables = []
        table_start = None

        for i, line in enumerate(lines):
            # Detect lines with multiple pipe or tab delimiters
            has_pipes = line.count("|") >= 2
            has_tabs = line.count("\t") >= 2
            has_aligned_spaces = bool(re.match(r"^\s*\S+\s{2,}\S+", line))

            if has_pipes or has_tabs or has_aligned_spaces:
                if table_start is None:
                    table_start = i
            else:
                if table_start is not None and i - table_start >= 2:
                    tables.append({
                        "type": "table",
                        "start_line": table_start,
                        "end_line": i - 1,
                        "row_count": i - table_start,
                    })
                table_start = None

        if table_start is not None:
            tables.append({
                "type": "table",
                "start_line": table_start,
                "end_line": len(lines) - 1,
                "row_count": len(lines) - table_start,
            })
        return tables

    def _detect_lists(self, lines: List[str]) -> List[Dict[str, Any]]:
        """Detect bulleted or numbered list regions."""
        lists = []
        list_start = None
        list_pattern = re.compile(
            r"^\s*([\-\*\+]|\d+[.\)]|[a-zA-Z][.\)])\s+"
        )

        for i, line in enumerate(lines):
            if list_pattern.match(line):
                if list_start is None:
                    list_start = i
            else:
                if list_start is not None and i - list_start >= 2:
                    lists.append({
                        "type": "list",
                        "start_line": list_start,
                        "end_line": i - 1,
                        "item_count": i - list_start,
                    })
                list_start = None

        if list_start is not None:
            lists.append({
                "type": "list",
                "start_line": list_start,
                "end_line": len(lines) - 1,
                "item_count": len(lines) - list_start,
            })
        return lists

    def _detect_paragraphs(
        self, lines: List[str], other_zones: List[Dict]
    ) -> List[Dict[str, Any]]:
        """Detect paragraph zones (contiguous non-empty lines not in other zones)."""
        occupied = set()
        for zone in other_zones:
            if "line_number" in zone:
                occupied.add(zone["line_number"])
            elif "start_line" in zone:
                for ln in range(zone["start_line"], zone["end_line"] + 1):
                    occupied.add(ln)

        paragraphs = []
        para_start = None

        for i, line in enumerate(lines):
            if i in occupied or not line.strip():
                if para_start is not None:
                    paragraphs.append({
                        "type": "paragraph",
                        "start_line": para_start,
                        "end_line": i - 1,
                    })
                    para_start = None
            else:
                if para_start is None:
                    para_start = i

        if para_start is not None:
            paragraphs.append({
                "type": "paragraph",
                "start_line": para_start,
                "end_line": len(lines) - 1,
            })
        return paragraphs

    def analyze(self, text: str) -> Dict[str, Any]:
        """Analyze document layout and return detected zones with reading order."""
        lines = text.split("\n")

        headers = self._detect_headers(lines)
        tables = self._detect_tables(lines)
        lists = self._detect_lists(lines)

        all_zones = headers + tables + lists
        paragraphs = self._detect_paragraphs(lines, all_zones)
        all_zones.extend(paragraphs)

        # Sort by line position to determine reading order
        def sort_key(zone):
            return zone.get("line_number", zone.get("start_line", 0))

        all_zones.sort(key=sort_key)

        for i, zone in enumerate(all_zones):
            zone["reading_order"] = i + 1

        return {
            "total_lines": len(lines),
            "zones": all_zones,
            "summary": {
                "headers": len(headers),
                "paragraphs": len(paragraphs),
                "tables": len(tables),
                "lists": len(lists),
            },
        }

"""Document Data Extractors for DocMind."""
import re
from typing import Dict, Any, List, Optional
from datetime import datetime


class InvoiceParser:
    """Extracts structured data from invoice text."""

    PATTERNS = {
        "invoice_number": [
            r"(?:invoice|inv)[\s#:]*([A-Z0-9\-]+)",
            r"(?:number|no\.?)[\s#:]*([A-Z0-9\-]+)",
        ],
        "date": [
            r"(?:date|dated)[:\s]*([\w\s,]+\d{4})",
            r"(\d{1,2}[/\-]\d{1,2}[/\-]\d{2,4})",
            r"(\w+\s+\d{1,2},?\s+\d{4})",
        ],
        "total_amount": [
            r"(?:total|amount\s*due|balance\s*due)[:\s]*\$?([\d,]+\.\d{2})",
            r"\$([\d,]+\.\d{2})",
        ],
        "company_name": [
            r"(?:bill\s*to|sold\s*to|customer)[:\s]*([A-Z][\w\s&,.]+)",
            r"(?:from|vendor)[:\s]*([A-Z][\w\s&,.]+)",
        ],
    }

    def parse(self, text: str) -> Dict[str, Any]:
        """Extract invoice fields from OCR text."""
        result = {}
        text_lower = text.lower()

        for field, patterns in self.PATTERNS.items():
            for pattern in patterns:
                match = re.search(pattern, text, re.IGNORECASE)
                if match:
                    result[field] = match.group(1).strip()
                    break

        # Extract line items (pattern: description + amount)
        line_items = []
        item_pattern = re.compile(
            r"^\s*(.+?)\s+\$?([\d,]+\.\d{2})\s*$", re.MULTILINE
        )
        for match in item_pattern.finditer(text):
            desc = match.group(1).strip()
            amount = match.group(2).strip()
            if len(desc) > 3 and not any(
                kw in desc.lower()
                for kw in ["total", "subtotal", "tax", "balance"]
            ):
                line_items.append({
                    "description": desc,
                    "amount": float(amount.replace(",", "")),
                })

        if line_items:
            result["line_items"] = line_items

        result["extraction_confidence"] = self._confidence(result)
        return result

    def _confidence(self, result: Dict) -> float:
        """Estimate extraction confidence based on fields found."""
        expected = ["invoice_number", "date", "total_amount"]
        found = sum(1 for f in expected if f in result)
        return round(found / len(expected), 2)


class ReceiptExtractor:
    """Extracts data from receipt text."""

    def extract(self, text: str) -> Dict[str, Any]:
        """Extract receipt data: store, items, total."""
        lines = text.strip().split("\n")
        result = {
            "store_name": lines[0].strip() if lines else "",
            "items": [],
            "total": None,
            "date": None,
        }

        # Find date
        for line in lines:
            date_match = re.search(
                r"(\d{1,2}[/\-]\d{1,2}[/\-]\d{2,4})", line
            )
            if date_match:
                result["date"] = date_match.group(1)
                break

        # Find items and total
        amount_pattern = re.compile(r"(.+?)\s+\$?([\d,]+\.\d{2})")
        for line in lines:
            match = amount_pattern.match(line.strip())
            if match:
                desc = match.group(1).strip()
                amount = float(match.group(2).replace(",", ""))
                if "total" in desc.lower():
                    result["total"] = amount
                elif len(desc) > 1:
                    result["items"].append({
                        "description": desc,
                        "amount": amount,
                    })

        return result


class DocumentExtractor:
    """General-purpose document data extractor."""

    def extract(self, text: str) -> Dict[str, Any]:
        """Extract common entities from document text."""
        result = {
            "emails": re.findall(r"[\w.+-]+@[\w-]+\.[\w.]+", text),
            "phones": re.findall(
                r"\+?\d?[\s\-]?\(?\d{3}\)?[\s\-]?\d{3}[\s\-]?\d{4}", text
            ),
            "dates": re.findall(
                r"\d{1,2}[/\-]\d{1,2}[/\-]\d{2,4}|\w+\s+\d{1,2},?\s+\d{4}",
                text,
            ),
            "amounts": [
                float(a.replace(",", ""))
                for a in re.findall(r"\$([\d,]+\.\d{2})", text)
            ],
            "addresses": self._extract_addresses(text),
            "names": self._extract_names(text),
        }
        return result

    def _extract_addresses(self, text: str) -> List[str]:
        """Extract potential street addresses."""
        pattern = re.compile(
            r"\d+\s+[A-Z][\w\s]+(?:St|Ave|Blvd|Dr|Rd|Ln|Way|Ct|Pl)"
            r"[\w\s,]*\d{5}(?:-\d{4})?",
            re.IGNORECASE,
        )
        return [m.strip() for m in pattern.findall(text)]

    def _extract_names(self, text: str) -> List[str]:
        """Extract potential person names (capitalized word pairs)."""
        pattern = re.compile(r"\b([A-Z][a-z]+\s+[A-Z][a-z]+)\b")
        candidates = pattern.findall(text)
        # Filter out common non-name phrases
        stop = {"Dear Sir", "Best Regards", "Thank You", "New York"}
        return [n for n in candidates if n not in stop]
